// formatDurasi mengubah menit menjadi format "X menit Y detik"
func formatDurasi(m int) string {
	if m < 1 {
		return "kurang dari 1 menit"
	}
	jam := m / 60
	menit := m % 60
	if jam > 0 {
		return fmt.Sprintf("%d jam %d menit", jam, menit)
	}
	return fmt.Sprintf("%d menit", menit)
}

